// ────────────────────────────────────────────────────────────
// MODULE: analyzer/stacking-context-resolver.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  Stacking Context Resolver
//  Giải mã Z thực sự — không phải chỉ đọc css z-index
// ============================================================

const MHQStackingResolver = (() => {

  function _tokens(value) {
    return String(value || "").split(/[\s,]+/).filter(Boolean);
  }

  function _hasAnyToken(value, list) {
    const tokens = _tokens(value);
    return list.some((item) => tokens.includes(item));
  }

  function _isNone(value) {
    return !value || value === "none" || value === "normal";
  }

  // Kiểm tra element có tạo stacking context không
  function getStackingContextReasons(el) {
    const s = getComputedStyle(el);
    const parentDisplay = el.parentElement ? getComputedStyle(el.parentElement).display : "";
    const isFlexOrGridItem = /flex|grid/.test(parentDisplay);
    const reasons = [];

    if (el === document.documentElement) reasons.push("root");
    if (s.position === "fixed") reasons.push("position:fixed");
    if (s.position === "sticky") reasons.push("position:sticky");
    if (s.position !== "static" && s.zIndex !== "auto") reasons.push("positioned-z-index");
    if (isFlexOrGridItem && s.zIndex !== "auto") reasons.push("flex-grid-z-index");
    if (parseFloat(s.opacity) < 1) reasons.push("opacity");
    if (!_isNone(s.transform)) reasons.push("transform");
    if (!_isNone(s.scale)) reasons.push("scale");
    if (!_isNone(s.rotate)) reasons.push("rotate");
    if (!_isNone(s.translate)) reasons.push("translate");
    if (!_isNone(s.filter)) reasons.push("filter");
    if (!_isNone(s.backdropFilter || s.webkitBackdropFilter)) reasons.push("backdrop-filter");
    if (!_isNone(s.perspective)) reasons.push("perspective");
    if (!_isNone(s.clipPath)) reasons.push("clip-path");
    if (!_isNone(s.maskImage || s.webkitMaskImage)) reasons.push("mask");
    if (s.isolation === "isolate") reasons.push("isolation");
    if (s.mixBlendMode !== "normal") reasons.push("mix-blend-mode");
    if (_hasAnyToken(s.contain, ["layout", "paint", "strict", "content"])) reasons.push("contain");
    if (s.containerType === "size" || s.containerType === "inline-size") reasons.push("container-type");
    if (_hasAnyToken(s.willChange, [
      "transform", "opacity", "filter", "backdrop-filter", "perspective",
      "clip-path", "mask", "left", "top", "contents"
    ])) reasons.push("will-change");

    return reasons;
  }

  function createsStackingContext(el) {
    return getStackingContextReasons(el).length > 0;
  }

  // Đếm bao nhiêu stacking context lồng nhau từ el lên root
  function resolveDepth(el) {
    let depth = 0;
    let node  = el.parentElement;
    while (node && node !== document.documentElement) {
      if (createsStackingContext(node)) depth++;
      node = node.parentElement;
    }
    return depth;
  }

  // Lấy z-index declared
  function getDeclaredZ(el) {
    const s   = getComputedStyle(el);
    const raw = parseInt(s.zIndex, 10);
    return isNaN(raw) ? 0 : raw;
  }

  // Paint order tương đối trong parent
  function resolvePaintOrder(el) {
    const siblings = Array.from(el.parentElement?.children || []);
    return siblings.indexOf(el);
  }

  function analyze(el) {
    const depth = resolveDepth(el);
    return {
      css_z_index_declared:      getDeclaredZ(el),
      creates_stacking_context:  createsStackingContext(el),
      stacking_context_reasons:  getStackingContextReasons(el),
      stacking_context_depth:    depth,
      resolved_paint_order:      resolvePaintOrder(el),
      webgl_z_normalized:        Math.min(depth / 10, 1.0),
    };
  }

  return { analyze, resolveDepth, createsStackingContext };
})();

// ────────────────────────────────────────────────────────────
// MODULE: analyzer/computed-style-extractor.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  Computed Style Extractor
//  Lấy những style QUAN TRỌNG — không lấy tất cả (quá nặng)
// ============================================================

const MHQStyleExtractor = (() => {

  const IMPORTANT_PROPS = [
    "display","position","top","left","right","bottom",
    "width","height","margin","padding","flex","flexDirection",
    "alignItems","justifyContent","gridTemplateColumns",
    "transform","opacity","visibility","overflow",
    "backgroundColor","color","fontSize","fontWeight",
    "zIndex","boxShadow","border","borderRadius",
    "transition","transitionProperty","transitionDuration","transitionDelay",
    "animation","animationName","animationDuration","animationPlayState",
    "willChange",
  ];

  function _maxTimeMs(value) {
    if (!value || value === "none") return 0;
    return value.split(",").reduce((max, part) => {
      const v = part.trim();
      if (!v) return max;
      const n = parseFloat(v);
      if (Number.isNaN(n)) return max;
      const ms = v.endsWith("ms") ? n : n * 1000;
      return Math.max(max, ms);
    }, 0);
  }

  function extract(el) {
    const computed = getComputedStyle(el);
    const snapshot = {};
    IMPORTANT_PROPS.forEach((prop) => {
      snapshot[prop] = computed[prop] || null;
    });

    const animationDuration = _maxTimeMs(snapshot.animationDuration);
    const animationNames    = (snapshot.animationName || "none").split(",").map((v) => v.trim());
    const playStates        = (snapshot.animationPlayState || "running").split(",").map((v) => v.trim());

    // Active CSS animations only. Declared transitions are metadata, not proof of motion.
    const isAnimating =
      animationDuration > 0 &&
      animationNames.some((name) => name && name !== "none") &&
      playStates.some((state) => state !== "paused");

    const hasTransition =
      _maxTimeMs(snapshot.transitionDuration) > 0 &&
      snapshot.transitionProperty !== "none";

    return {
      properties:     snapshot,
      is_animating:   isAnimating,
      has_transition: hasTransition,
      current_transform: snapshot.transform,
    };
  }

  return { extract };
})();

// ────────────────────────────────────────────────────────────
// MODULE: analyzer/dom-crawler.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  MH-QUANTUM — dom-crawler.js (PATCHED v2.1)
//  BUG FIX:
//  [#7] elementFromPoint bị overlay chặn → tạm disable pointer-events
//  [#8] XPath sai với root element → fix loop condition + undefined tag
// ============================================================

const MHQDomCrawler = (() => {

  function rectsOverlap(r1, r2) {
    return !(
      r1.right  < r2.left  ||
      r1.left   > r2.right ||
      r1.bottom < r2.top   ||
      r1.top    > r2.bottom
    );
  }

  // ── [PATCHED] elementFromPoint — Fix Bug #7 ─────────────
  // Tạm tắt pointer-events của overlay để "nhìn xuyên" qua nó
  function getElementAtPoint(x, y) {
    const overlay = document.getElementById("mhq-overlay");
    const oldPointerEvents = overlay?.style.pointerEvents || "";

    // Disable overlay temporarily
    if (overlay) overlay.style.pointerEvents = "none";

    let el = null;
    try {
      el = document.elementFromPoint(x, y);
    } finally {
      if (overlay) overlay.style.pointerEvents = oldPointerEvents;
    }

    // Fallback nếu vẫn không tìm được element thật
    if (!el || el === overlay || el === document.body) {
      return document.body;
    }
    return el;
  }

  // ── CSS Selector builder ─────────────────────────────────
  function getSelector(el) {
    const parts = [];
    let node     = el;

    while (node && node.nodeType === 1 && node !== document.documentElement) {
      let seg = node.tagName.toLowerCase();
      if (node.id) {
        seg += `#${node.id}`;
        parts.unshift(seg);
        break; // ID unique → stop here
      } else if (node.className) {
        const cls = Array.from(node.classList).slice(0, 3).join(".");
        if (cls) seg += `.${cls}`;
      }
      parts.unshift(seg);
      node = node.parentElement;
    }

    return parts.join(" > ") || el.tagName.toLowerCase();
  }

  // ── [PATCHED] XPath builder — Fix Bug #8 ─────────────────
  // Bug gốc: parentNode có thể là Document (nodeType=9)
  //          → node.tagName = undefined → "/undefined[1]/..."
  // Fix: loop CHỈ khi nodeType === 1 (Element)
  //      và dừng trước document.documentElement
  function getXPath(el) {
    if (el.id) return `//*[@id="${el.id}"]`;

    const parts = [];
    let node     = el;

    while (node && node.nodeType === 1) {
      // [FIX] Dừng khi đến <html> element
      if (node === document.documentElement) {
        parts.unshift("html");
        break;
      }

      const tag = node.tagName.toLowerCase();
      let idx   = 1;
      let sib   = node.previousSibling;

      while (sib) {
        if (
          sib.nodeType === 1 &&
          sib.tagName.toLowerCase() === tag  // [FIX] lowercase compare
        ) {
          idx++;
        }
        sib = sib.previousSibling;
      }

      parts.unshift(`${tag}[${idx}]`);

      // [FIX] parentElement thay vì parentNode → luôn trả về Element hoặc null
      node = node.parentElement;
    }

    return "/" + parts.join("/");
  }

  // ── Element description ──────────────────────────────────
  function describeElement(el) {
    if (!el || el.nodeType !== 1) return null;

    const rect    = el.getBoundingClientRect();
    const zData   = MHQStackingResolver.analyze(el);
    const styles  = MHQStyleExtractor.extract(el);

    return {
      tag:          el.tagName.toLowerCase(),
      id:           el.id   || null,
      classes:      Array.from(el.classList),
      css_selector: getSelector(el),
      xpath:        getXPath(el),
      bounding_box: {
        top:    Math.round(rect.top),
        left:   Math.round(rect.left),
        bottom: Math.round(rect.bottom),
        right:  Math.round(rect.right),
        width:  Math.round(rect.width),
        height: Math.round(rect.height),
      },
      z_analysis:     zData,
      computed_styles: styles.properties,
      is_animating:   styles.is_animating,
      text_content:   el.textContent?.trim().slice(0, 80) || null,
    };
  }

  // ── Find elements in region ──────────────────────────────
  function findElementsInRegion(selectionRect) {
    const all     = document.querySelectorAll("*");
    const results = [];
    const limit   = window.MHQuantumConfig?.analyzer?.max_elements_in_region || 50;

    for (const el of all) {
      // Skip tool's own elements
      if (
        el.closest("#mhq-overlay") ||
        el.closest("#mhq-panel")   ||
        el.closest("#mhq-toast")
      ) continue;

      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) continue;

      if (rectsOverlap(r, selectionRect)) {
        const desc = describeElement(el);
        if (desc) results.push(desc);
        if (results.length >= limit) break;
      }
    }

    // Sort: nổi nhất (z-depth cao) lên trước
    results.sort(
      (a, b) =>
        b.z_analysis.stacking_context_depth -
        a.z_analysis.stacking_context_depth
    );

    return results;
  }

  return {
    findElementsInRegion,
    describeElement,
    getElementAtPoint,  // [NEW] exported để quantum-engine.js dùng
    getSelector,
    getXPath,
  };
})();

// ────────────────────────────────────────────────────────────
// MODULE: core/temporal-observer.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  MH-QUANTUM — temporal-observer.js (BẢN VÁ v2.1)
//  SỬA LỖI:
//  [#6] Điểm mù trục T (T-axis blindspot) — tự động phát hiện hoạt ảnh chạy bằng JS
//       (GSAP, Framer Motion, Web Animations API, RAF inline)
// ============================================================

const MHQTemporalObserver = (() => {

  let rafId    = null;
  let frameIdx = 0;

  // MutationObserver theo dõi inline style changes (GSAP/Framer)
  let mutationObserver = null;
  const recentlyMutated = new WeakSet();

  function start() {
    if (rafId || mutationObserver) return;

    frameIdx = 0;

    // RAF counter
    function tick() {
      frameIdx++;
      rafId = requestAnimationFrame(tick);
    }
    rafId = requestAnimationFrame(tick);

    // MutationObserver để nhận diện hoạt ảnh chạy bằng JS (JS-driven animation)
    // Khi GSAP/Framer thay đổi thuộc tính style/class → đánh dấu element đang chuyển động
    mutationObserver = new MutationObserver((mutations) => {
      mutations.forEach((m) => {
        if (
          m.type === "attributes" &&
          (m.attributeName === "style" || m.attributeName === "class")
        ) {
          recentlyMutated.add(m.target);
          // Clear flag sau 200ms
          setTimeout(() => recentlyMutated.delete(m.target), 200);
        }
      });
    });

    mutationObserver.observe(document.body, {
      attributes:    true,
      subtree:       true,
      attributeFilter: ["style", "class"],
    });

    console.log("[MHQ Temporal] ✅ Bộ giám sát thời gian đã kích hoạt (Đang quét chuyển động CSS + JS)");
  }

  function stop() {
    if (rafId) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
    if (mutationObserver) {
      mutationObserver.disconnect();
      mutationObserver = null;
    }
    frameIdx = 0;
  }

  // ── [BẢN VÁ] captureT — Khắc phục lỗi #6 ─────────────────────
  function captureT(el) {
    const styleInfo = MHQStyleExtractor.extract(el);

    // Phương pháp 1: Chỉ tính hoạt ảnh CSS đang hoạt động. Các transition khai báo sẵn nhưng không chạy sẽ coi là tĩnh.
    const hasCSSAnimation = styleInfo.is_animating;

    // Phương pháp 2: Web Animations API (CSS transitions, Framer Motion, anime.js...)
    let hasWebAnimation = false;
    let webAnimationDetails = null;
    if (typeof el.getAnimations === "function") {
      const runningAnims = el.getAnimations().filter(
        (a) => a.playState === "running" || a.playState === "pending"
      );
      if (runningAnims.length > 0) {
        hasWebAnimation = true;
        webAnimationDetails = runningAnims.map((a) => ({
          type:       a.constructor.name,
          playState:  a.playState,
          currentTime: a.currentTime,
        }));
      }
    }

    // Phương pháp 3: MutationObserver — Theo dõi thay đổi inline style bằng JS (GSAP, RAF)
    const hasJSAnimation = recentlyMutated.has(el);

    // ── Tổng hợp kết quả ──
    const isActuallyAnimating = hasCSSAnimation || hasWebAnimation || hasJSAnimation;

    // Tự động thích ứng: trả về null nếu phần tử THỰC SỰ tĩnh (không chuyển động)
    if (!isActuallyAnimating) return null;

    const computedTransform = getComputedStyle(el).transform;
    const computedOpacity   = parseFloat(getComputedStyle(el).opacity);

    return {
      performance_now_ms:    parseFloat(performance.now().toFixed(3)),
      iso_timestamp:         new Date().toISOString(),
      animation_frame_index: frameIdx,
      detection_method: {
        css_animation:       hasCSSAnimation,
        web_animations_api:  hasWebAnimation,
        js_driven_mutation:  hasJSAnimation,
      },
      web_animation_details: webAnimationDetails,
      element_state_at_T: {
        is_animating:      true,
        current_transform: computedTransform,
        opacity:           computedOpacity,
        inline_style:      el.getAttribute("style") || null,
      },
    };
  }

  return { start, stop, captureT };
})();

// ────────────────────────────────────────────────────────────
// MODULE: core/dimension-sampler.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  Dimension Sampler
//  Thu thập vector 4D: X, Y, Z, T
// ============================================================

const MHQDimensionSampler = (() => {

  function sample(el, mouseX, mouseY) {
    const rect      = el.getBoundingClientRect();
    const zAnalysis = MHQStackingResolver.analyze(el);
    const tAxis     = MHQTemporalObserver.captureT(el);  // null nếu không animate
    const styles    = MHQStyleExtractor.extract(el);
    const dpr       = window.devicePixelRatio || 1;

    return {
      X: {
        viewport_relative:   Math.round(rect.left),
        absolute_with_scroll: Math.round(rect.left + window.scrollX),
        normalized_0to1:     parseFloat((rect.left / window.innerWidth).toFixed(4)),
        mouse_x:             Math.round(mouseX),
      },
      Y: {
        viewport_relative:   Math.round(rect.top),
        absolute_with_scroll: Math.round(rect.top + window.scrollY),
        normalized_0to1:     parseFloat((rect.top / window.innerHeight).toFixed(4)),
        mouse_y:             Math.round(mouseY),
      },
      Z: zAnalysis,
      T: tAxis,  // null nếu element tĩnh — adaptive dimension
    };
  }

  return { sample };
})();

// ────────────────────────────────────────────────────────────
// MODULE: renderer/webgl-context.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  WebGL Context Manager
//  Khởi tạo, compile shader, fallback nếu WebGL không available
// ============================================================

const MHQWebGL = (() => {
  let gl = null;
  let program = null;

  function init(canvas) {
    if (gl) return true;

    try {
      gl = canvas.getContext("webgl", {
        alpha: true,
        premultipliedAlpha: false,
        antialias: true,
      });
      if (!gl) throw new Error("WebGL not supported");

      gl.enable(gl.BLEND);
      gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
      gl.clearColor(0, 0, 0, 0);

      return true;
    } catch (e) {
      console.warn("[MHQ] WebGL unavailable:", e.message);
      gl = null;
      return false;
    }
  }

  function compileShader(src, type) {
    const shader = gl.createShader(type);
    gl.shaderSource(shader, src);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      console.error("[MHQ Shader Error]", gl.getShaderInfoLog(shader));
      gl.deleteShader(shader);
      return null;
    }
    return shader;
  }

  function buildProgram(vertSrc, fragSrc) {
    if (!gl) return false;
    if (program) {
      gl.useProgram(program);
      return true;
    }

    const vert = compileShader(vertSrc, gl.VERTEX_SHADER);
    const frag = compileShader(fragSrc, gl.FRAGMENT_SHADER);
    if (!vert || !frag) {
      if (vert) gl.deleteShader(vert);
      if (frag) gl.deleteShader(frag);
      return false;
    }

    const nextProgram = gl.createProgram();
    gl.attachShader(nextProgram, vert);
    gl.attachShader(nextProgram, frag);
    gl.linkProgram(nextProgram);

    gl.detachShader(nextProgram, vert);
    gl.detachShader(nextProgram, frag);
    gl.deleteShader(vert);
    gl.deleteShader(frag);

    if (!gl.getProgramParameter(nextProgram, gl.LINK_STATUS)) {
      console.error("[MHQ Program Error]", gl.getProgramInfoLog(nextProgram));
      gl.deleteProgram(nextProgram);
      program = null;
      return false;
    }

    program = nextProgram;
    gl.useProgram(program);
    return true;
  }

  function destroyProgram() {
    if (gl && program) {
      gl.deleteProgram(program);
      program = null;
    }
  }

  function getGL()      { return gl; }
  function getProgram() { return program; }

  function resize(canvas) {
    canvas.width  = window.innerWidth;
    canvas.height = window.innerHeight;
    if (gl) gl.viewport(0, 0, canvas.width, canvas.height);
  }

  return { init, buildProgram, destroyProgram, getGL, getProgram, resize };
})();

// ────────────────────────────────────────────────────────────
// MODULE: renderer/quantum-mesh-builder.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  MH-QUANTUM — quantum-mesh-builder.js (PATCHED v2.1)
//  BUG FIX:
//  [#3] Z-Clipping — ortho matrix now includes near/far plane
// ============================================================

const MHQMeshBuilder = (() => {

  function buildMeshVertices(rect, zDepth, segments = 12) {
    const { left, top, right, bottom } = rect;
    const verts  = [];
    const alphas = [];

    const W      = right  - left;
    const H      = bottom - top;
    const zScale = Math.min(zDepth * 4, 40); // max 40, safe với near=-100 far=100

    function pushVertex(x, y, z, alpha) {
      verts.push(x, y, z);
      alphas.push(alpha);
    }

    function pushLine(x1, y1, z1, x2, y2, z2, alpha) {
      pushVertex(x1, y1, z1, alpha);
      pushVertex(x2, y2, z2, alpha);
    }

    // ── Perimeter edges — explicit pairs for gl.LINES ─────────
    const perimeter = [];
    for (let i = 0; i <= segments; i++) {
      const t = i / segments;
      perimeter.push([left + t * W, top, zScale * Math.sin(t * Math.PI)]);
    }
    for (let i = 1; i <= segments; i++) {
      const t = i / segments;
      perimeter.push([right, top + t * H, zScale * Math.sin(t * Math.PI)]);
    }
    for (let i = 1; i <= segments; i++) {
      const t = i / segments;
      perimeter.push([right - t * W, bottom, zScale * Math.sin(t * Math.PI)]);
    }
    for (let i = 1; i <= segments; i++) {
      const t = i / segments;
      perimeter.push([left, bottom - t * H, zScale * Math.sin(t * Math.PI)]);
    }
    perimeter.push(perimeter[0]);

    for (let i = 0; i < perimeter.length - 1; i++) {
      const a = perimeter[i];
      const b = perimeter[i + 1];
      pushLine(a[0], a[1], a[2], b[0], b[1], b[2], 0.9);
    }

    // ── Internal grid ────────────────────────────────────
    const gridX = 4, gridY = 4;
    for (let i = 1; i < gridX; i++) {
      const x = left + (W / gridX) * i;
      pushLine(x, top, 0, x, bottom, 0, 0.25);
    }
    for (let i = 1; i < gridY; i++) {
      const y = top + (H / gridY) * i;
      pushLine(left, y, 0, right, y, 0, 0.25);
    }

    // ── Corner markers ───────────────────────────────────
    const corners = [
      [left,  top],
      [right, top],
      [right, bottom],
      [left,  bottom],
    ];
    const csz = 12;
    corners.forEach(([x, y]) => {
      pushLine(x - csz, y, zScale, x + csz, y, zScale, 1.0);
      pushLine(x, y - csz, zScale, x, y + csz, zScale, 1.0);
    });

    return {
      positions: new Float32Array(verts),
      alphas:    new Float32Array(alphas),
      count:     verts.length / 3,
    };
  }

  // ── [PATCHED] Orthographic matrix — Fix Bug #3 ──────────
  // Thêm near/far plane để normalize Z về [-1, 1]
  // near = -100, far = 100 → safe với zScale max = 40
  // Ma trận column-major (WebGL convention):
  //
  //  [ 2/w,       0,          0,          0 ]
  //  [ 0,        -2/h,        0,          0 ]
  //  [ 0,         0,         -2/depth,    0 ]
  //  [ -1,        1,         -(f+n)/depth, 1 ]
  //
  function buildOrthoMatrix(w, h, near = -100, far = 100) {
    const depth = far - near;

    return new Float32Array([
      2 / w,            0,              0,                    0,
          0,       -2 / h,              0,                    0,
          0,            0,      -2 / depth,                   0,
         -1,            1, -(far + near) / depth,             1,
    ]);
  }

  return { buildMeshVertices, buildOrthoMatrix };
})();

// ────────────────────────────────────────────────────────────
// MODULE: renderer/hud-overlay.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  HUD Overlay — Canvas 2D vẽ labels, thông số đè lên WebGL
// ============================================================

const MHQHud = (() => {

  let ctx2d = null;
  let hudCanvas = null;

  function init() {
    hudCanvas = document.createElement("canvas");
    hudCanvas.id = "mhq-hud";
    hudCanvas.style.cssText = `
      position:absolute; inset:0;
      width:100%; height:100%;
      pointer-events:none;
    `;
    ctx2d = hudCanvas.getContext("2d");
    return hudCanvas;
  }

  function resize() {
    if (!hudCanvas) return;
    hudCanvas.width  = window.innerWidth;
    hudCanvas.height = window.innerHeight;
  }

  function clear() {
    if (ctx2d) ctx2d.clearRect(0, 0, hudCanvas.width, hudCanvas.height);
  }

  function drawDimensionLabels(matrix4D, rect) {
    if (!ctx2d) return;
    const { X, Y, Z, T } = matrix4D;
    const { left, top, right, bottom } = rect;

    ctx2d.font         = "11px 'Courier New', monospace";
    ctx2d.fillStyle    = "#00FFAA";
    ctx2d.shadowColor  = "#00FFAA";
    ctx2d.shadowBlur   = 8;

    const lines = [
      `X: ${X.viewport_relative} | Y: ${Y.viewport_relative}`,
      `Z-stack: ${Z.stacking_context_depth} | paint#${Z.resolved_paint_order}`,
      T ? `T: ${T.performance_now_ms.toFixed(2)}ms` : null,
    ].filter(Boolean);

    const px = left;
    const py = top - 8 - (lines.length * 15);

    lines.forEach((line, i) => {
      ctx2d.fillText(line, px, py + i * 15);
    });

    // Corner brackets
    ctx2d.strokeStyle = "#00FFAA";
    ctx2d.lineWidth   = 1.5;
    ctx2d.shadowBlur  = 6;
    const b = 10;
    [
      [left,  top,    b,  b],
      [right, top,   -b,  b],
      [right, bottom,-b, -b],
      [left,  bottom, b, -b],
    ].forEach(([x, y, dx, dy]) => {
      ctx2d.beginPath();
      ctx2d.moveTo(x + dx, y);
      ctx2d.lineTo(x, y);
      ctx2d.lineTo(x, y + dy);
      ctx2d.stroke();
    });

    ctx2d.shadowBlur = 0;
  }

  return { init, resize, clear, drawDimensionLabels };
})();

// ────────────────────────────────────────────────────────────
// MODULE: transport/e2e-cipher.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  MH-QUANTUM — e2e-cipher.js (PATCHED v2.1)
//  BUG FIX:
//  [#1] Key mismatch — đồng bộ HKDF giữa client & server
//  [#2] Stack overflow — safe Base64 encoder
// ============================================================

const MHQCipher = (() => {

  let sharedKey = null;

  // ── [NEW] Safe Base64 encoder — Fix Bug #2 ──────────────
  // Không dùng spread operator → không overflow call stack
  // Safe với payload bất kỳ kích thước nào (ảnh, JSON lớn...)
  function _safeBytesToBase64(bytes) {
    let binary = "";
    const len  = bytes.byteLength;
    // Chunk 8192 bytes để tránh cả string concat overhead
    const CHUNK = 8192;
    for (let i = 0; i < len; i += CHUNK) {
      const slice = bytes.subarray(i, Math.min(i + CHUNK, len));
      for (let j = 0; j < slice.length; j++) {
        binary += String.fromCharCode(slice[j]);
      }
    }
    return btoa(binary);
  }

  // ── Generate ECDH key pair ───────────────────────────────
  async function generateKeyPair() {
    return crypto.subtle.generateKey(
      { name: "ECDH", namedCurve: "P-256" },
      true,
      ["deriveBits"]  // [FIX #1] deriveBits thay vì deriveKey
    );
  }

  // ── Export public key → base64 ───────────────────────────
  async function exportPublicKey(keyPair) {
    const raw = await crypto.subtle.exportKey("raw", keyPair.publicKey);
    // "raw" format = 65-byte uncompressed point (0x04 prefix)
    // Compatible với Node.js ecdh.generateKeys("buffer")
    return _safeBytesToBase64(new Uint8Array(raw));
  }

  // ── Import server's public key ───────────────────────────
  async function importServerPublicKey(b64) {
    const raw = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    return crypto.subtle.importKey(
      "raw",
      raw,
      { name: "ECDH", namedCurve: "P-256" },
      true,
      []  // public key không cần usage
    );
  }

  // ── [PATCHED] Derive AES key — Fix Bug #1 ───────────────
  // Đồng bộ hoàn toàn với Node.js hkdfSync ở server:
  //   salt  = 32 bytes zero
  //   info  = "MHQ-AES-KEY" (UTF-8)
  //   hash  = SHA-256
  //   length = 256 bits
  async function deriveSharedKey(privateKey, serverPublicKey) {
    // Step 1: Lấy raw shared secret (256 bits = X coordinate)
    const rawSecretBits = await crypto.subtle.deriveBits(
      { name: "ECDH", public: serverPublicKey },
      privateKey,
      256
    );

    // Step 2: Import làm HKDF key
    const hkdfKey = await crypto.subtle.importKey(
      "raw",
      rawSecretBits,
      { name: "HKDF" },
      false,
      ["deriveKey"]
    );

    // Step 3: Derive AES-256-GCM — SAME params as server
    sharedKey = await crypto.subtle.deriveKey(
      {
        name: "HKDF",
        hash: "SHA-256",
        salt: new Uint8Array(32),                     // 32 bytes 0 — match server
        info: new TextEncoder().encode("MHQ-AES-KEY") // match server
      },
      hkdfKey,
      { name: "AES-GCM", length: 256 },
      false,
      ["encrypt", "decrypt"]
    );

    console.log("[MHQ Cipher] ✅ Shared key derived via HKDF-SHA256");
  }

  // ── [PATCHED] Encrypt — Fix Bug #2 ──────────────────────
  async function encrypt(plaintext) {
    if (!sharedKey) throw new Error("[MHQ] No shared key — handshake first");

    const iv  = crypto.getRandomValues(new Uint8Array(12));
    const ct  = await crypto.subtle.encrypt(
      { name: "AES-GCM", iv },
      sharedKey,
      new TextEncoder().encode(plaintext)
    );

    return {
      iv:         _safeBytesToBase64(iv),                    // Fix #2
      ciphertext: _safeBytesToBase64(new Uint8Array(ct)),    // Fix #2
    };
  }

  // ── Decrypt ──────────────────────────────────────────────
  async function decrypt(iv_b64, ct_b64) {
    if (!sharedKey) throw new Error("[MHQ] No shared key");

    const iv = Uint8Array.from(atob(iv_b64), (c) => c.charCodeAt(0));
    const ct = Uint8Array.from(atob(ct_b64), (c) => c.charCodeAt(0));

    const pt = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv },
      sharedKey,
      ct
    );
    return new TextDecoder().decode(pt);
  }

  function hasKey() { return sharedKey !== null; }

  function reset() {
    sharedKey = null;
    console.log("[MHQ Cipher] 🔑 Key reset");
  }

  return {
    generateKeyPair,
    exportPublicKey,
    importServerPublicKey,
    deriveSharedKey,
    encrypt,
    decrypt,
    hasKey,
    reset,
  };
})();

// ────────────────────────────────────────────────────────────
// MODULE: transport/payload-schema.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  Payload Schema + Auto-Prompt Generator
//  "AI-Proof Context Package" — AI không còn lý do kháng cự
// ============================================================

const MHQPayloadSchema = (() => {

  function build(matrix4D, domContext, viewportCtx, intentText, visualArtifact) {
    const payload = {
      inspector_version: "MH-Quantum-v2.1",
      session_id:        crypto.randomUUID(),
      spatial_matrix_4D: matrix4D,
      bounding_box:      domContext.primary_element?.bounding_box || null,
      dom_context:       domContext,
      viewport_context:  viewportCtx,
      quantum_mesh_render: {
        artifact_type:      _artifactType(visualArtifact),
        screenshot_base64:  typeof visualArtifact === "string" ? visualArtifact : null,
        dom_snapshot:       visualArtifact?.type === "dom_snapshot" ? visualArtifact : null,
      },
      user_intent: intentText || "(không có)",
      auto_prompt: _generatePrompt(matrix4D, domContext, intentText),
      timestamp: new Date().toISOString(),
    };
    return payload;
  }

  function _artifactType(artifact) {
    if (typeof artifact === "string") return "screenshot_base64";
    return artifact?.type || null;
  }

  function _generatePrompt(matrix4D, domContext, intent) {
    const el    = domContext.primary_element;
    const lang  = window.MHQuantumConfig?.ai_prompt?.language || "vi";
    const count = domContext.element_count;

    if (lang === "vi") {
      return `
[MH-QUANTUM INSPECTOR — CONTEXT PACKAGE]

Tôi đang inspect element sau trên trang web:
- Thẻ/Selector: ${el?.css_selector || "N/A"}
- XPath: ${el?.xpath || "N/A"}
- Classes: ${el?.classes?.join(", ") || "none"}
- Vị trí (X/Y viewport): ${matrix4D.X.viewport_relative}px / ${matrix4D.Y.viewport_relative}px
- Kích thước: ${el?.bounding_box?.width}x${el?.bounding_box?.height}px
- Z stacking depth: ${matrix4D.Z.stacking_context_depth} | Z-index CSS: ${matrix4D.Z.css_z_index_declared}
${matrix4D.T ? `- Đang animate: YES | Timestamp: ${matrix4D.T.performance_now_ms}ms` : "- Trạng thái: TĨNH (không animate)"}
- Tổng elements trong vùng chọn: ${count}

Ý định của tôi: ${intent || "(chưa điền)"}

Hãy dựa vào toàn bộ context trên để trả lời chính xác, không hỏi lại.
`.trim();
    } else {
      return `
[MH-QUANTUM INSPECTOR — CONTEXT PACKAGE]

Inspecting element:
- Selector: ${el?.css_selector || "N/A"}
- XPath: ${el?.xpath || "N/A"}
- Position: X=${matrix4D.X.viewport_relative}px Y=${matrix4D.Y.viewport_relative}px
- Size: ${el?.bounding_box?.width}x${el?.bounding_box?.height}px
- Z-stack depth: ${matrix4D.Z.stacking_context_depth}
${matrix4D.T ? `- Animating: YES | T=${matrix4D.T.performance_now_ms}ms` : "- Static element"}
- Elements in region: ${count}

User intent: ${intent || "(none)"}

Answer based on full context above.
`.trim();
    }
  }

  return { build };
})();

// ────────────────────────────────────────────────────────────
// MODULE: transport/ws-client.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  WebSocket Client — 3-Tier Fallback Transport
//  Tier 1: WebSocket E2E encrypted
//  Tier 2: Clipboard
//  Tier 3: Export JSON file
// ============================================================

const MHQTransport = (() => {

  let ws         = null;
  let keyPair    = null;
  let connected  = false;
  let retries    = 0;
  const MAX_RETRIES = window.MHQuantumConfig?.transport?.reconnect_attempts || 3;

  function isConnected() {
    return !!(
      connected &&
      ws &&
      ws.readyState === WebSocket.OPEN &&
      MHQCipher.hasKey()
    );
  }

  function _setConnected(ok) {
    connected = ok;
    _updateStatus(ok);
  }

  async function connect() {
    const url = window.MHQuantumConfig?.transport?.websocket_url || "ws://localhost:9001";
    try {
      _setConnected(false);
      MHQCipher.reset();
      keyPair = await MHQCipher.generateKeyPair();
      const pubKeyB64 = await MHQCipher.exportPublicKey(keyPair);

      ws = new WebSocket(url);

      ws.onopen = async () => {
        // ECDH handshake — gửi public key
        ws.send(JSON.stringify({ type: "HANDSHAKE", publicKey: pubKeyB64 }));
      };

      ws.onmessage = async (evt) => {
        try {
          const msg = JSON.parse(evt.data);
          if (msg.type === "HANDSHAKE_ACK") {
            const serverPub = await MHQCipher.importServerPublicKey(msg.publicKey);
            await MHQCipher.deriveSharedKey(keyPair.privateKey, serverPub);
            retries = 0;
            _setConnected(true);
            console.log("[MHQ] 🔐 WebSocket E2E connected & encrypted");
          }
        } catch (e) {
          console.warn("[MHQ] WS message failed:", e.message);
          _setConnected(false);
        }
      };

      ws.onclose = () => {
        _setConnected(false);
        MHQCipher.reset();
        if (retries < MAX_RETRIES) {
          retries++;
          const delay = window.MHQuantumConfig?.transport?.reconnect_delay_ms || 1500;
          console.warn(`[MHQ] WS closed. Retry ${retries}/${MAX_RETRIES}...`);
          setTimeout(connect, delay);
        }
      };

      ws.onerror = (e) => {
        _setConnected(false);
        console.warn("[MHQ] WS error:", e);
      };

    } catch (e) {
      _setConnected(false);
      console.warn("[MHQ] Cannot connect to WS server:", e.message);
    }
  }

  async function send(payload) {
    const json = JSON.stringify(payload);

    // ── TIER 1: WebSocket E2E ──
    if (isConnected()) {
      try {
        const encrypted = await MHQCipher.encrypt(json);
        ws.send(JSON.stringify({ type: "PAYLOAD", ...encrypted }));
        MHQToast.show("✅ Đã gửi qua WebSocket (E2E)", "success");
        return;
      } catch (e) {
        _setConnected(false);
        console.warn("[MHQ] WS send failed, falling back:", e);
      }
    }

    // ── TIER 2: Clipboard ──
    try {
      const text = payload.auto_prompt + "\n\n---\n" + JSON.stringify(payload, null, 2);
      await navigator.clipboard.writeText(text);
      MHQToast.show("📋 Đã copy vào Clipboard (WS offline)", "warn");
      return;
    } catch (e) {
      console.warn("[MHQ] Clipboard failed, falling back to file:", e);
    }

    // ── TIER 3: Export JSON File ──
    _exportFile(json, `mhq-${Date.now()}.json`);
    MHQToast.show("💾 Đã xuất file JSON (offline mode)", "warn");
  }

  function _exportFile(content, filename) {
    const blob = new Blob([content], { type: "application/json" });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement("a");
    a.href     = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  }

  function _updateStatus(isConnectedNow) {
    const dot = document.getElementById("mhq-status-dot");
    if (dot) dot.classList.toggle("connected", isConnectedNow);
    if (typeof MHQPanel !== "undefined" && MHQPanel.updateStatus) {
      MHQPanel.updateStatus(isConnectedNow);
    }
  }

  return { connect, send, isConnected };
})();

// ────────────────────────────────────────────────────────────
// MODULE: ui/toast.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  Toast Notification
// ============================================================

const MHQToast = (() => {

  let el      = null;
  let timeout = null;

  function init() {
    if (el) return;
    el    = document.createElement("div");
    el.id = "mhq-toast";
    document.body.appendChild(el);
  }

  function show(message, type = "success", duration = 2800) {
    if (!el) return;
    const safeType = ["success", "warn", "error"].includes(type) ? type : "success";
    el.textContent = message;
    el.className   = `show ${safeType}`;
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(() => {
      el.classList.remove("show");
    }, duration);
  }

  return { init, show };
})();

// ────────────────────────────────────────────────────────────
// MODULE: ui/control-panel.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  Control Panel — Mini floating panel
// ============================================================

const MHQPanel = (() => {

  let panel = null;

  function init() {
    if (panel) return;

    panel = document.createElement("div");
    panel.id        = "mhq-panel";
    panel.innerHTML = `
      <div id="mhq-panel-title">⚡ MH-QUANTUM v2.1</div>
      <div>
        <span id="mhq-status-dot"></span>
        <span id="mhq-status-text">Disconnected</span>
      </div>
      <div style="margin-top:8px;font-size:11px;opacity:0.6;">
        Hotkey: Ctrl+Shift+X &nbsp;|&nbsp; Drag để chọn vùng
      </div>
      <textarea
        id="mhq-intent-input"
        rows="2"
        placeholder="Anh muốn làm gì với element này? (optional)"
      ></textarea>
      <div style="margin-top:8px;display:flex;gap:6px;">
        <button id="mhq-btn-close" style="
          flex:1;background:transparent;border:1px solid #FF4444;
          color:#FF4444;font-family:monospace;font-size:11px;
          border-radius:4px;padding:4px;cursor:pointer;
        ">✕ Đóng</button>
        <button id="mhq-btn-clear" style="
          flex:1;background:transparent;border:1px solid #00FFAA;
          color:#00FFAA;font-family:monospace;font-size:11px;
          border-radius:4px;padding:4px;cursor:pointer;
        ">↺ Clear</button>
      </div>
    `;
    document.body.appendChild(panel);

    document.getElementById("mhq-btn-close").onclick  = () => MHQEngine.deactivate();
    document.getElementById("mhq-btn-clear").onclick  = () => {
      document.getElementById("mhq-intent-input").value = "";
    };
  }

  function show() {
    if (panel) panel.classList.add("active");
    updateStatus();
  }

  function hide() {
    if (panel) panel.classList.remove("active");
  }

  function getIntent() {
    return document.getElementById("mhq-intent-input")?.value?.trim() || "";
  }

  function updateStatus(forceConnected) {
    const dot  = document.getElementById("mhq-status-dot");
    const text = document.getElementById("mhq-status-text");
    if (!dot || !text) return;

    const ok = typeof forceConnected === "boolean"
      ? forceConnected
      : (typeof MHQTransport !== "undefined" && MHQTransport.isConnected());

    dot.classList.toggle("connected", ok);
    text.textContent = ok ? "WebSocket E2E 🔐" : "Offline mode";
  }

  return { init, show, hide, getIntent, updateStatus };
})();

// ────────────────────────────────────────────────────────────
// MODULE: core/quantum-engine.js
// ────────────────────────────────────────────────────────────
// ============================================================
//  MH-QUANTUM — quantum-engine.js (PATCHED v2.1)
//  BUG FIX:
//  [#4] GPU buffer leak + RAF runaway → reuse buffers, cancel properly
//  [#5] Screenshot async bug + popup hell → dom-snapshot fallback
//  [#7] elementFromPoint → dùng MHQDomCrawler.getElementAtPoint()
//  [FIX 2.2] Contextual Popup + StatusBar thay panel cố định
// ============================================================

const MHQEngine = (() => {

  // ── State ──────────────────────────────────────────────
  let active   = false;
  let dragging = false;
  let startX   = 0, startY = 0;
  let endX     = 0, endY   = 0;

  let _pendingSelRect = null;   // Lưu selection rect khi chờ intent
  let _pendingMouseX  = 0;
  let _pendingMouseY  = 0;

  // ── DOM refs ───────────────────────────────────────────
  let overlay    = null;
  let canvas     = null;
  let selBox     = null;
  let xhairLabel = null;
  let hudCanvas  = null;

  // ── WebGL state ────────────────────────────────────────
  let useWebGL   = false;
  let animRAF    = null;
  let meshData   = null;
  let startTime  = 0;

  // ── [FIX #4] Persistent GPU buffers ───────────────────
  let glPosBuffer   = null;
  let glAlphaBuffer = null;

  // ── Shader sources (inline) ────────────────────────────
  const VERT_SRC = `
    attribute vec3  a_position;
    attribute float a_alpha;
    uniform   mat4  u_matrix;
    uniform   float u_time;
    uniform   float u_z_depth;
    varying   float v_alpha;
    varying   float v_z_depth;

    void main() {
      float pulse = sin(u_time * 2.0 + a_position.x * 0.05) * 0.5 + 0.5;
      vec3  pos   = a_position;
      pos.z += sin(u_time * 1.5 + a_position.y * 0.03) * u_z_depth * 2.0;
      gl_Position  = u_matrix * vec4(pos, 1.0);
      gl_PointSize = 3.0;
      v_alpha      = a_alpha * (0.7 + pulse * 0.3);
      v_z_depth    = u_z_depth;
    }
  `;

  const FRAG_SRC = `
    precision mediump float;
    uniform float u_time;
    uniform float u_z_depth;
    varying float v_alpha;
    varying float v_z_depth;

    void main() {
      float t   = clamp(v_z_depth / 10.0, 0.0, 1.0);
      vec3  c1  = vec3(0.0,  1.0,  0.667); // #00FFAA
      vec3  c2  = vec3(1.0,  0.0,  1.0);   // #FF00FF
      vec3  col = mix(c1, c2, t);
      float flicker = 0.92 + 0.08 * sin(u_time * 8.0);
      gl_FragColor  = vec4(col * flicker, v_alpha);
    }
  `;

  // ── Init ───────────────────────────────────────────────
  function init() {
    _buildDOM();
    _bindHotkey();

    // [CHANGED] Dùng StatusBar + ContextPopup thay Panel cũ
    MHQStatusBar.init();
    MHQContextPopup.init();
    MHQToast.init();

    MHQTemporalObserver.start();
    MHQTransport.connect();
    console.log("[MHQ Engine] 🚀 MH-Quantum-Inspector v2.1 initialized");
  }

  function _buildDOM() {
    overlay        = document.createElement("div");
    overlay.id     = "mhq-overlay";

    canvas         = document.createElement("canvas");
    canvas.id      = "mhq-canvas";

    selBox         = document.createElement("div");
    selBox.id      = "mhq-selection-box";

    xhairLabel     = document.createElement("div");
    xhairLabel.id  = "mhq-crosshair-label";

    hudCanvas      = MHQHud.init();

    overlay.append(canvas, selBox, xhairLabel, hudCanvas);
    document.body.appendChild(overlay);

    _bindMouseEvents();
    window.addEventListener("resize", _onResize);
  }

  function _onResize() {
    MHQWebGL.resize(canvas);
    MHQHud.resize();
  }

  // ── Hotkey ─────────────────────────────────────────────
  function _bindHotkey() {
    const cfg = window.MHQuantumConfig?.hotkey || {
      key: "X", ctrl: true, shift: true
    };

    document.addEventListener("keydown", (e) => {
      const match =
        e.key === cfg.key   &&
        e.ctrlKey  === cfg.ctrl  &&
        e.shiftKey === cfg.shift;

      if (match) {
        e.preventDefault();
        active ? deactivate() : activate();
      }

      if (e.key === "Escape" && active) deactivate();
    });
  }

  // ── Activate ───────────────────────────────────────────
  function activate() {
    active    = true;
    startTime = performance.now();

    overlay.classList.add("active");

    // [CHANGED] StatusBar thay vì Panel
    MHQStatusBar.show();

    if (window.MHQuantumConfig?.renderer?.prefer_webgl !== false) {
      useWebGL = MHQWebGL.init(canvas);
      if (useWebGL) {
        MHQWebGL.resize(canvas);
        useWebGL = MHQWebGL.buildProgram(VERT_SRC, FRAG_SRC);
        if (!useWebGL) {
          console.warn("[MHQ Engine] WebGL program failed — mesh disabled");
        }

        const gl = MHQWebGL.getGL();
        if (useWebGL && gl && !glPosBuffer) {
          glPosBuffer   = gl.createBuffer();
          glAlphaBuffer = gl.createBuffer();
          console.log("[MHQ Engine] 🎮 WebGL persistent buffers created");
        }
      }
    }

    MHQHud.resize();
    MHQToast.show("⚡ MH-Quantum ACTIVE — Ctrl+Shift+X để tắt");
    console.log("[MHQ Engine] ✅ Activated");
  }

  // ── Deactivate ─────────────────────────────────────────
  function deactivate() {
    active   = false;
    dragging = false;

    // [CHANGED] Ẩn cả ContextPopup + StatusBar
    MHQContextPopup.hide();
    MHQStatusBar.hide();

    if (animRAF) {
      cancelAnimationFrame(animRAF);
      animRAF = null;
    }

    const gl = MHQWebGL.getGL();
    if (gl) {
      if (glPosBuffer)   { gl.deleteBuffer(glPosBuffer);   glPosBuffer   = null; }
      if (glAlphaBuffer) { gl.deleteBuffer(glAlphaBuffer); glAlphaBuffer = null; }
      gl.clear(gl.COLOR_BUFFER_BIT);
      console.log("[MHQ Engine] 🧹 WebGL buffers cleaned up");
    }

    meshData = null;
    window.removeEventListener("mouseup", _onMouseUp, true);

    overlay.classList.remove("active");
    selBox.style.display     = "none";
    xhairLabel.style.display = "none";
    MHQHud.clear();

    // Reset pending state
    _pendingSelRect = null;
    _pendingMouseX  = 0;
    _pendingMouseY  = 0;
  }

  // ── Mouse Events ───────────────────────────────────────
  function _bindMouseEvents() {
    overlay.addEventListener("mousedown", _onMouseDown);
    overlay.addEventListener("mousemove", _onMouseMove);
    overlay.addEventListener("mouseup",   _onMouseUp);
  }

  function _onMouseDown(e) {
    if (!active) return;
    dragging = true;
    startX   = e.clientX;
    startY   = e.clientY;
    endX     = e.clientX;
    endY     = e.clientY;
    window.addEventListener("mouseup", _onMouseUp, true);

    selBox.style.display = "block";
    MHQHud.clear();

    if (animRAF) {
      cancelAnimationFrame(animRAF);
      animRAF  = null;
      meshData = null;
    }
  }

  function _onMouseMove(e) {
    if (!active) return;

    xhairLabel.style.display = "block";
    xhairLabel.style.left    = `${e.clientX + 16}px`;
    xhairLabel.style.top     = `${e.clientY + 10}px`;
    xhairLabel.textContent   = `X:${e.clientX}  Y:${e.clientY}`;

    if (!dragging) return;
    endX = e.clientX;
    endY = e.clientY;

    const r = _getSelectionRect();
    selBox.style.left   = `${r.left}px`;
    selBox.style.top    = `${r.top}px`;
    selBox.style.width  = `${r.right  - r.left}px`;
    selBox.style.height = `${r.bottom - r.top}px`;
  }

  // ── [CHANGED] _onMouseUp — bật popup ngay tại selection ───
  async function _onMouseUp(e) {
    if (!active || !dragging) return;
    dragging = false;
    endX     = e.clientX;
    endY     = e.clientY;

    const selRect = _getSelectionRect();
    const W       = selRect.right  - selRect.left;
    const H       = selRect.bottom - selRect.top;

    if (W < 6 || H < 6) {
      selBox.style.display = "none";
      return;
    }

    // Lưu context, bật popup NGAY TẠI vùng selection
    _pendingSelRect = selRect;
    _pendingMouseX  = e.clientX;
    _pendingMouseY  = e.clientY;

    // Lấy element tag để hiển thị trong popup header
    const el  = MHQDomCrawler.getElementAtPoint(e.clientX, e.clientY);
    const tag = el
      ? MHQDomCrawler.getSelector(el).split(">").pop().trim()
      : "element";

    // Show contextual popup sát vùng selection
    MHQContextPopup.show(
      selRect,
      tag,
      // onSend callback — user đã điền intent → process
      async (intent) => {
        await _processSelection(
          _pendingSelRect,
          _pendingMouseX,
          _pendingMouseY,
          intent   // intent được pass trực tiếp từ popup
        );
      },
      // onCancel callback — user hủy
      () => {
        selBox.style.display = "none";
        MHQHud.clear();
        const gl = MHQWebGL.getGL();
        if (gl) gl.clear(gl.COLOR_BUFFER_BIT);
        MHQToast.show("↩ Đã hủy", "warn", 1200);
      }
    );
  }

  // ── [CHANGED] _processSelection signature mới ─────────
  // Thêm tham số intent (không đọc từ panel nữa)
  async function _processSelection(selRect, mouseX, mouseY, intent = "") {
    MHQToast.show("🔍 Đang phân tích...", "success", 900);

    try {
      const primaryEl = MHQDomCrawler.getElementAtPoint(mouseX, mouseY);
      if (!primaryEl) {
        MHQToast.show("⚠️ Không tìm được element", "error");
        return;
      }

      const elements   = MHQDomCrawler.findElementsInRegion(selRect);
      if (elements.length === 0) {
        MHQToast.show("⚠️ Không có element trong vùng chọn", "error");
        return;
      }

      const primaryData = MHQDomCrawler.describeElement(primaryEl);
      const matrix4D    = MHQDimensionSampler.sample(primaryEl, mouseX, mouseY);
      const styleInfo   = MHQStyleExtractor.extract(primaryEl);

      const viewportCtx = {
        window_width:       window.innerWidth,
        window_height:      window.innerHeight,
        scroll_x:           window.scrollX,
        scroll_y:           window.scrollY,
        device_pixel_ratio: window.devicePixelRatio || 1,
        zoom_level:         parseFloat(
          (window.outerWidth / window.innerWidth).toFixed(2)
        ),
      };

      const domSnapshot = _captureDOMSnapshot(primaryEl, selRect);

      const domContext = {
        primary_element: {
          ...primaryData,
          computed_styles: styleInfo.properties,
        },
        all_elements_in_region: elements,
        element_count:          elements.length,
      };

      // intent từ popup, không từ panel
      const payload = MHQPayloadSchema.build(
        matrix4D, domContext, viewportCtx, intent, domSnapshot
      );

      if (useWebGL) _renderQuantumMesh(selRect, matrix4D.Z);
      MHQHud.drawDimensionLabels(matrix4D, selRect);

      await MHQTransport.send(payload);

      console.log("[MHQ Engine] 📦 Session:", payload.session_id);

      if (intent) {
        MHQToast.show(`🚀 Đã gửi: "${intent.slice(0, 40)}..."`, "success");
      } else {
        MHQToast.show("📦 Đã gửi payload (không có intent)", "success");
      }

    } catch (err) {
      console.error("[MHQ Engine] ❌ Error:", err);
      MHQToast.show(`❌ Lỗi: ${err.message}`, "error", 4000);
    }
  }

  // ── WebGL Render — Fix Bug #4 ──────────────────────────
  function _renderQuantumMesh(rect, zData) {
    const gl      = MHQWebGL.getGL();
    const program = MHQWebGL.getProgram();
    if (!gl || !program || !glPosBuffer || !glAlphaBuffer) return;

    meshData     = MHQMeshBuilder.buildMeshVertices(rect, zData.stacking_context_depth);
    const near = window.MHQuantumConfig?.renderer?.z_near ?? -100;
    const far  = window.MHQuantumConfig?.renderer?.z_far  ?? 100;
    const matrix = MHQMeshBuilder.buildOrthoMatrix(
      canvas.width, canvas.height,
      near, far
    );

    gl.bindBuffer(gl.ARRAY_BUFFER, glPosBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, meshData.positions, gl.DYNAMIC_DRAW);
    const posLoc = gl.getAttribLocation(program, "a_position");
    gl.enableVertexAttribArray(posLoc);
    gl.vertexAttribPointer(posLoc, 3, gl.FLOAT, false, 0, 0);

    gl.bindBuffer(gl.ARRAY_BUFFER, glAlphaBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, meshData.alphas, gl.DYNAMIC_DRAW);
    const alphaLoc = gl.getAttribLocation(program, "a_alpha");
    gl.enableVertexAttribArray(alphaLoc);
    gl.vertexAttribPointer(alphaLoc, 1, gl.FLOAT, false, 0, 0);

    const matLoc  = gl.getUniformLocation(program, "u_matrix");
    const timeLoc = gl.getUniformLocation(program, "u_time");
    const zLoc    = gl.getUniformLocation(program, "u_z_depth");

    gl.uniformMatrix4fv(matLoc, false, matrix);
    gl.uniform1f(zLoc, zData.stacking_context_depth);

    function frame() {
      if (!meshData) return;

      const t = (performance.now() - startTime) / 1000;
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.uniform1f(timeLoc, t);
      gl.drawArrays(gl.LINES, 0, meshData.count);
      animRAF = requestAnimationFrame(frame);
    }
    frame();
  }

  // ── DOM Snapshot — Fix Bug #5 ──────────────────────────
  function _captureDOMSnapshot(el, rect) {
    if (!window.MHQuantumConfig?.analyzer?.collect_screenshot) return null;

    try {
      const children = Array.from(el.querySelectorAll("*"))
        .slice(0, 20)
        .map((child) => ({
          tag:        child.tagName.toLowerCase(),
          classes:    Array.from(child.classList),
          text:       child.textContent?.trim().slice(0, 60) || null,
          rect: (() => {
            const r = child.getBoundingClientRect();
            return { w: Math.round(r.width), h: Math.round(r.height) };
          })(),
        }));

      return {
        type: "dom_snapshot",
        note: "Screenshot replaced by DOM snapshot (no permission required)",
        selection_region: {
          width:  Math.round(rect.right  - rect.left),
          height: Math.round(rect.bottom - rect.top),
        },
        outer_html_preview: el.outerHTML.slice(0, 500),
        children_summary:   children,
        child_count:        el.querySelectorAll("*").length,
      };
    } catch (e) {
      console.warn("[MHQ Engine] DOM snapshot failed:", e.message);
      return null;
    }
  }

  // ── Helpers ────────────────────────────────────────────
  function _getSelectionRect() {
    return {
      left:   Math.min(startX, endX),
      top:    Math.min(startY, endY),
      right:  Math.max(startX, endX),
      bottom: Math.max(startY, endY),
    };
  }

  return { init, activate, deactivate };
})();

// ── Auto-init ──────────────────────────────────────────────
document.addEventListener("DOMContentLoaded", () => MHQEngine.init());
